export const ADMIN_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Pass Studio — Admin</title>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js\"></script>\n<style>\n  :root{\n    --bg:#f6f6f4; --panel:#fff; --ink:#1a1a1a; --ink-soft:#6b6b6b; --line:#e7e5e0;\n    --crimson:#a4133c; --crimson-deep:#800f2f; --blush:#fff0f3; --good:#1a7f4e; --chip:#f1efe9;\n    --card-bg:linear-gradient(160deg,#800f2f 0%,#a4133c 55%,#c9184a 100%);\n  }\n  *{box-sizing:border-box;margin:0;padding:0;}\n  body{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Inter,Roboto,sans-serif;background:var(--bg);color:var(--ink);min-height:100vh;}\n\n  .topbar{display:flex;align-items:center;gap:14px;padding:12px 22px;background:var(--panel);border-bottom:1px solid var(--line);}\n  .brandmark{display:flex;align-items:center;gap:9px;font-weight:700;font-size:15px;}\n  .brandmark .dot{width:26px;height:26px;border-radius:8px;background:var(--card-bg);display:grid;place-items:center;color:#fff;font-size:13px;}\n  .crumb{color:var(--ink-soft);font-size:13px;}\n  .topbar .right{margin-left:auto;display:flex;gap:10px;align-items:center;}\n  .btn{border:1px solid var(--line);background:#fff;padding:8px 14px;border-radius:9px;font-size:13px;font-weight:600;cursor:pointer;font-family:inherit;color:var(--ink);transition:all .13s;}\n  .btn:hover{border-color:#cfcbc2;}\n  .btn.primary{background:var(--crimson);border-color:var(--crimson);color:#fff;}\n  .btn.primary:hover{background:var(--crimson-deep);}\n  .btn.ghost{border-color:transparent;color:var(--ink-soft);}\n  .btn:disabled{opacity:.5;cursor:default;}\n\n  .wrap{max-width:980px;margin:0 auto;padding:26px 22px 60px;}\n\n  /* key gate */\n  .gate{max-width:420px;margin:80px auto;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:28px;text-align:center;}\n  .gate .dot{width:44px;height:44px;border-radius:13px;background:var(--card-bg);display:grid;place-items:center;color:#fff;font-size:21px;margin:0 auto 14px;}\n  .gate h1{font-size:18px;margin-bottom:6px;}\n  .gate p{font-size:13px;color:var(--ink-soft);margin-bottom:18px;line-height:1.5;}\n  .gate input{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px 13px;font-size:14px;font-family:inherit;margin-bottom:12px;text-align:center;}\n  .gate .err{color:var(--crimson);font-size:12.5px;margin-top:10px;display:none;}\n\n  /* list */\n  .head-row{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;}\n  .head-row h1{font-size:19px;}\n  .head-row .sub{font-size:13px;color:var(--ink-soft);margin-top:3px;}\n  .list{background:var(--panel);border:1px solid var(--line);border-radius:14px;overflow:hidden;}\n  .row{display:flex;align-items:center;gap:14px;padding:14px 18px;border-bottom:1px solid var(--line);}\n  .row:last-child{border-bottom:0;}\n  .row .name{font-size:14px;font-weight:700;}\n  .row .name .ev{font-weight:500;color:var(--ink-soft);font-size:13px;}\n  .row .serial{font-family:ui-monospace,Menlo,monospace;font-size:11.5px;}\n  .row.archived{opacity:.55;background:#fbfaf7;}\n  .arch-tag{font-size:9.5px;font-weight:800;letter-spacing:.8px;color:var(--ink-soft);background:var(--chip);padding:2px 7px;border-radius:99px;vertical-align:middle;}\n  .row .meta{font-size:12px;color:var(--ink-soft);margin-top:3px;}\n  .row .grow{flex:1;min-width:0;}\n  .pill{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:700;padding:4px 10px;border-radius:99px;}\n  .pill.live{background:#e8f5ee;color:var(--good);}\n  .pill.live::before{content:\"\";width:7px;height:7px;border-radius:50%;background:var(--good);}\n  .pill.idle{background:var(--chip);color:var(--ink-soft);}\n  .row .actions{display:flex;gap:8px;}\n  .empty{padding:46px;text-align:center;color:var(--ink-soft);font-size:14px;line-height:1.6;}\n\n  /* modal */\n  .overlay{position:fixed;inset:0;background:rgba(20,10,14,.45);display:none;align-items:center;justify-content:center;z-index:50;padding:20px;}\n  .overlay.show{display:flex;}\n  .modal{background:#fff;border-radius:16px;max-width:440px;width:100%;padding:22px;box-shadow:0 24px 70px -20px rgba(0,0,0,.4);}\n  .modal h2{font-size:16px;margin-bottom:4px;}\n  .modal .sub{font-size:12.5px;color:var(--ink-soft);margin-bottom:16px;font-family:ui-monospace,Menlo,monospace;}\n  .modal label{display:block;font-size:11px;font-weight:700;letter-spacing:.6px;color:var(--ink-soft);margin:12px 0 5px;}\n  .modal input,.modal textarea{width:100%;border:1px solid var(--line);border-radius:9px;padding:10px 12px;font-size:13.5px;font-family:inherit;resize:vertical;}\n  .modal textarea{min-height:74px;}\n  .modal .foot{display:flex;justify-content:flex-end;gap:10px;margin-top:18px;}\n  .modal .note{font-size:12px;color:var(--ink-soft);margin-top:12px;line-height:1.5;}\n  .fields-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 14px;}\n  #qrBox{display:grid;place-items:center;padding:10px 0 4px;}\n  #qrBox img{border:1px solid var(--line);border-radius:12px;padding:10px;background:#fff;}\n\n  .toast{position:fixed;bottom:26px;left:50%;transform:translateX(-50%) translateY(8px);background:var(--ink);color:#fff;font-size:13px;padding:10px 18px;border-radius:99px;opacity:0;transition:all .25s;pointer-events:none;z-index:99;}\n  .toast.show{opacity:1;transform:translateX(-50%) translateY(0);}\n  .demo-badge{background:#ffd166;color:#5c4400;font-size:11px;font-weight:800;padding:3px 10px;border-radius:99px;letter-spacing:.5px;}\n</style>\n</head>\n<body>\n\n<div class=\"topbar\">\n  <div class=\"brandmark\"><div class=\"dot\">♥</div> Pass Studio</div>\n  <div class=\"crumb\">All About Love · Kindness Card</div>\n  <span class=\"demo-badge\" id=\"demoBadge\" style=\"display:none\">DEMO DATA</span>\n  <div class=\"right\">\n    <button class=\"btn\" id=\"newCardBtn\" style=\"display:none\">＋ New test card</button>\n    <button class=\"btn ghost\" id=\"lockBtn\" style=\"display:none\">Sign out</button>\n  </div>\n</div>\n\n<!-- key gate -->\n<div class=\"gate\" id=\"gate\">\n  <div class=\"dot\">♥</div>\n  <h1>Pass Studio Admin</h1>\n  <p>Enter your admin key to manage cards.<br>It stays on this device.</p>\n  <input type=\"password\" id=\"keyInput\" placeholder=\"Admin key\" onkeydown=\"if(event.key==='Enter')connect()\">\n  <button class=\"btn primary\" style=\"width:100%\" onclick=\"connect()\">Connect</button>\n  <div class=\"err\" id=\"gateErr\">That key was rejected — check it and try again.</div>\n</div>\n\n<!-- main -->\n<div class=\"wrap\" id=\"main\" style=\"display:none\">\n  <div class=\"head-row\">\n    <div>\n      <h1>Cards</h1>\n      <div class=\"sub\" id=\"countSub\">—</div>\n    </div>\n    <button class=\"btn\" onclick=\"loadPasses()\">↻ Refresh</button>\n  </div>\n  <div class=\"list\" id=\"list\"><div class=\"empty\">Loading…</div></div>\n</div>\n\n<!-- notify modal -->\n<div class=\"overlay\" id=\"notifyOverlay\">\n  <div class=\"modal\">\n    <h2>Send a notification</h2>\n    <div class=\"sub\" id=\"notifySerial\"></div>\n    <label>MESSAGE (APPEARS ON THE LOCK SCREEN)</label>\n    <textarea id=\"notifyMsg\" placeholder=\"Your act of kindness ends tomorrow.\"></textarea>\n    <div class=\"note\">Delivered to every iPhone this card is installed on. Apple mutes cards that are updated too frequently — in production, keep to the reminder schedule.</div>\n    <div class=\"foot\">\n      <button class=\"btn\" onclick=\"hide('notifyOverlay')\">Cancel</button>\n      <button class=\"btn primary\" id=\"notifySend\" onclick=\"sendNotify()\">➤ Send</button>\n    </div>\n  </div>\n</div>\n\n<!-- edit modal -->\n<div class=\"overlay\" id=\"editOverlay\">\n  <div class=\"modal\">\n    <h2>Edit card fields</h2>\n    <div class=\"sub\" id=\"editSerial\"></div>\n    <div class=\"fields-grid\">\n      <div><label>GUEST</label><input id=\"f_guest\"></div>\n      <div><label>EVENT</label><input id=\"f_event\"></div>\n      <div><label>DUE</label><input id=\"f_due\"></div>\n      <div><label>ACTS DONE</label><input id=\"f_acts\"></div>\n    </div>\n    <label>PROMISE (FRONT OF CARD)</label><input id=\"f_promise\">\n    <label>THE MOVEMENT</label><input id=\"f_movement\">\n    <div class=\"note\">Saving pushes the changes silently to installed cards (no notification unless you also send a message).</div>\n    <div class=\"foot\">\n      <button class=\"btn\" onclick=\"hide('editOverlay')\">Cancel</button>\n      <button class=\"btn primary\" onclick=\"saveFields()\">Save & push</button>\n    </div>\n  </div>\n</div>\n\n<!-- google save-link modal -->\n<div class=\"overlay\" id=\"googleOverlay\">\n  <div class=\"modal\">\n    <h2>Save to Google Wallet</h2>\n    <div class=\"sub\" id=\"googleSerial\"></div>\n    <div id=\"googleBody\"><div class=\"note\" style=\"text-align:center\">Creating the Google pass…</div></div>\n    <div class=\"note\">Demo mode: only accounts listed in your Google Wallet console (admins & test users) can save this card until publishing access is granted. Scan with an Android phone, or open the link in a browser signed into your Google account.</div>\n    <div class=\"foot\">\n      <button class=\"btn\" id=\"googleCopy\" style=\"display:none\" onclick=\"copyGoogleLink()\">Copy link</button>\n      <button class=\"btn\" onclick=\"hide('googleOverlay')\">Done</button>\n    </div>\n  </div>\n</div>\n\n<!-- new card modal -->\n<div class=\"overlay\" id=\"qrOverlay\">\n  <div class=\"modal\">\n    <h2>Add a test card to an iPhone</h2>\n    <div class=\"sub\">Scan with the iPhone camera → opens in Safari → Add</div>\n    <div id=\"qrBox\"></div>\n    <div class=\"note\" id=\"qrUrlNote\" style=\"text-align:center\"></div>\n    <div class=\"foot\">\n      <button class=\"btn\" onclick=\"hide('qrOverlay')\">Done</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nconst DEMO = new URLSearchParams(location.search).has('demo');\nconst BASE = DEMO ? '' : location.origin;\nlet KEY = null, currentSerial = null;\n\n/* ── demo data ── */\nconst demoPasses = [\n  { serial: 'b6efd3a4-0af3-45aa-9041-4b6e079afd27', guest: 'Sarah', event: 'Rivera Wedding', created_at: Date.now()/1000-3600, updated_at: Date.now()/1000-120, registrations: 1 },\n  { serial: '8fb5edf0-b3a3-465c-bbea-9df620e998e2', guest: 'Marcus', event: 'Rivera Wedding', created_at: Date.now()/1000-7200, updated_at: Date.now()/1000-3800, registrations: 0 },\n  { serial: '713c1514-120a-49af-b54f-926cc06938e2', guest: null, event: null, created_at: Date.now()/1000-90000, updated_at: Date.now()/1000-90000, registrations: 0 },\n];\nconst demoFields = { guest:'Sarah', event:'Rivera Wedding', due:'Aug 11', acts:'0', promise:'I promised an act of kindness', movement:'Act #247,801 of one million' };\n\nasync function api(path, opts = {}) {\n  if (DEMO) return demoApi(path, opts);\n  const res = await fetch(BASE + path, {\n    ...opts,\n    headers: { 'X-Admin-Key': KEY, 'Content-Type': 'application/json', ...(opts.headers||{}) },\n  });\n  if (res.status === 401) throw new Error('unauthorized');\n  return res.json();\n}\nasync function demoApi(path, opts) {\n  await new Promise(r=>setTimeout(r,250));\n  if (path === '/v1/passes' && !opts.method) return { passes: demoPasses };\n  if (path.includes('/google-link')) return { saveUrl: 'https://pay.google.com/gp/v/save/DEMO.JWT.LINK' };\n  if (opts.method === 'POST' && path.includes('action=archive')) { demoPasses.find(p=>path.includes(p.serial)).archived_at = Date.now()/1000; return { ok:true }; }\n  if (opts.method === 'POST' && path.includes('action=unarchive')) { demoPasses.find(p=>path.includes(p.serial)).archived_at = null; return { ok:true }; }\n  if (opts.method === 'PATCH') return { ok:true, pushed:1, results:[{device:'demo',status:200}] };\n  if (path.startsWith('/v1/passes/')) return { fields: demoFields };\n  return {};\n}\n\n/* ── auth flow ── */\nasync function connect() {\n  KEY = document.getElementById('keyInput').value.trim();\n  if (!KEY && !DEMO) return;\n  try {\n    await api('/v1/passes');\n    localStorage.setItem('psk', KEY || 'demo');\n    enter();\n  } catch { document.getElementById('gateErr').style.display = 'block'; }\n}\nfunction enter() {\n  document.getElementById('gate').style.display = 'none';\n  document.getElementById('main').style.display = 'block';\n  document.getElementById('newCardBtn').style.display = '';\n  document.getElementById('lockBtn').style.display = '';\n  loadPasses();\n}\ndocument.getElementById('lockBtn').onclick = () => { localStorage.removeItem('psk'); location.reload(); };\ndocument.getElementById('newCardBtn').onclick = showQr;\n\n/* ── list ── */\nfunction rel(ts) {\n  const s = Math.max(1, Math.floor(Date.now()/1000 - ts));\n  if (s < 90) return s + 's ago';\n  if (s < 5400) return Math.round(s/60) + 'm ago';\n  if (s < 129600) return Math.round(s/3600) + 'h ago';\n  return Math.round(s/86400) + 'd ago';\n}\nlet showArchived = false;\nfunction passRow(p) {\n  const archived = !!p.archived_at;\n  return `\n      <div class=\"row${archived ? ' archived' : ''}\">\n        <div class=\"grow\">\n          <div class=\"name\">${esc(p.guest) || 'Unnamed card'}${p.event ? ' <span class=\"ev\">· ' + esc(p.event) + '</span>' : ''}${archived ? ' <span class=\"arch-tag\">ARCHIVED</span>' : ''}</div>\n          <div class=\"meta\"><span class=\"serial\">${p.serial.slice(0,8)}…</span> · created ${rel(p.created_at)} · updated ${rel(p.updated_at)}</div>\n        </div>\n        ${p.registrations>0\n          ? '<span class=\"pill live\">'+p.registrations+' device'+(p.registrations===1?'':'s')+'</span>'\n          : '<span class=\"pill idle\">not added yet</span>'}\n        <div class=\"actions\">${archived\n          ? `<button class=\"btn\" onclick=\"unarchivePass('${p.serial}')\">↩︎ Unarchive</button>`\n          : `<button class=\"btn\" ${p.registrations?'':'disabled'} onclick=\"showNotify('${p.serial}')\">🔔 Notify</button>\n             <button class=\"btn\" onclick=\"showEdit('${p.serial}')\">✎ Edit</button>\n             <button class=\"btn\" onclick=\"showGoogleLink('${p.serial}')\" title=\"Save to Google Wallet link\">G</button>\n             <button class=\"btn\" onclick=\"archivePass('${p.serial}')\">🗄 Archive</button>`}\n        </div>\n      </div>`;\n}\nasync function loadPasses() {\n  const list = document.getElementById('list');\n  try {\n    const data = await api('/v1/passes');\n    const all = data.passes || [];\n    const active = all.filter(p => !p.archived_at);\n    const archived = all.filter(p => p.archived_at);\n    document.getElementById('countSub').innerHTML =\n      active.length + ' card' + (active.length===1?'':'s') + ' · ' +\n      active.filter(p=>p.registrations>0).length + ' installed on a device' +\n      (archived.length ? ` · <a href=\"#\" onclick=\"showArchived=!showArchived;loadPasses();return false\" style=\"color:var(--crimson)\">${showArchived?'hide':'show'} ${archived.length} archived</a>` : '');\n    const visible = showArchived ? [...active, ...archived] : active;\n    if (!visible.length) { list.innerHTML = '<div class=\"empty\">No cards yet.<br>Mint one with “＋ New test card”.</div>'; return; }\n    list.innerHTML = visible.map(passRow).join('');\n  } catch (e) {\n    list.innerHTML = '<div class=\"empty\">Could not load — ' + e.message + '</div>';\n  }\n}\n\n/* ── notify ── */\nfunction showNotify(serial) {\n  currentSerial = serial;\n  document.getElementById('notifySerial').textContent = serial;\n  document.getElementById('notifyMsg').value = '';\n  show('notifyOverlay');\n  document.getElementById('notifyMsg').focus();\n}\nasync function sendNotify() {\n  const msg = document.getElementById('notifyMsg').value.trim();\n  if (!msg) return;\n  const btn = document.getElementById('notifySend'); btn.disabled = true;\n  try {\n    const r = await api('/v1/passes/'+currentSerial, { method:'PATCH', body: JSON.stringify({ changeMessage: msg }) });\n    hide('notifyOverlay');\n    toast(r.pushed ? '🔔 Sent to '+r.pushed+' device'+(r.pushed===1?'':'s') : 'Saved — no devices registered');\n    loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n  btn.disabled = false;\n}\n\n/* ── edit ── */\nconst FIELD_IDS = ['guest','event','due','acts','promise','movement'];\nasync function showEdit(serial) {\n  currentSerial = serial;\n  document.getElementById('editSerial').textContent = serial;\n  show('editOverlay');\n  try {\n    const data = await api('/v1/passes/'+serial);\n    for (const k of FIELD_IDS) document.getElementById('f_'+k).value = (data.fields||{})[k] ?? '';\n  } catch(e){ toast('Failed to load: '+e.message); }\n}\nasync function saveFields() {\n  const fields = {};\n  for (const k of FIELD_IDS) fields[k] = document.getElementById('f_'+k).value;\n  try {\n    await api('/v1/passes/'+currentSerial, { method:'PATCH', body: JSON.stringify({ fields }) });\n    hide('editOverlay'); toast('Saved & pushed ✓'); loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n}\n\n/* ── google save link ── */\nlet googleLink = null;\nasync function showGoogleLink(serial) {\n  currentSerial = serial;\n  document.getElementById('googleSerial').textContent = serial;\n  document.getElementById('googleBody').innerHTML = '<div class=\"note\" style=\"text-align:center\">Creating the Google pass…</div>';\n  document.getElementById('googleCopy').style.display = 'none';\n  show('googleOverlay');\n  try {\n    const data = await api('/v1/passes/'+serial+'/google-link');\n    if (!data.saveUrl) throw new Error(data.error || 'no link returned');\n    googleLink = data.saveUrl;\n    const qr = qrcode(0, 'M'); qr.addData(data.saveUrl); qr.make();\n    document.getElementById('googleBody').innerHTML =\n      '<div id=\"qrBoxG\" style=\"display:grid;place-items:center;padding:6px 0\">'+qr.createImgTag(3,8)+'</div>' +\n      '<div class=\"note\" style=\"text-align:center\"><a href=\"'+data.saveUrl+'\" target=\"_blank\" rel=\"noopener\">Open save link ↗</a></div>';\n    document.getElementById('googleCopy').style.display = '';\n  } catch(e){\n    document.getElementById('googleBody').innerHTML = '<div class=\"note\" style=\"color:var(--crimson)\">Failed: '+esc(e.message)+'</div>';\n  }\n}\nfunction copyGoogleLink(){ if(googleLink){ navigator.clipboard.writeText(googleLink); toast('Link copied'); } }\n\n/* ── new card QR ── */\nfunction showQr() {\n  const url = (DEMO ? 'https://digital-pass.small-bread-a578.workers.dev' : location.origin) + '/v1/test-pass';\n  const qr = qrcode(0, 'M'); qr.addData(url); qr.make();\n  document.getElementById('qrBox').innerHTML = qr.createImgTag(5, 10);\n  document.getElementById('qrUrlNote').textContent = url;\n  show('qrOverlay');\n}\n\n/* ── archive (data is never destroyed) ── */\nasync function archivePass(serial) {\n  try {\n    await api('/v1/passes/'+serial+'?action=archive', { method:'POST' });\n    toast('🗄 Archived — find it under \"show archived\"');\n    loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n}\nasync function unarchivePass(serial) {\n  try {\n    await api('/v1/passes/'+serial+'?action=unarchive', { method:'POST' });\n    toast('Restored to active cards');\n    loadPasses();\n  } catch(e){ toast('Failed: '+e.message); }\n}\n\n/* ── utils ── */\nfunction esc(s){ return s ? String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])) : s; }\nfunction show(id){ document.getElementById(id).classList.add('show'); }\nfunction hide(id){ document.getElementById(id).classList.remove('show'); }\nfunction toast(t){ const el=document.getElementById('toast'); el.textContent=t; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2600); }\n\n/* ── boot ── */\nif (DEMO) {\n  document.getElementById('demoBadge').style.display = '';\n  KEY = 'demo'; enter();\n} else {\n  const saved = localStorage.getItem('psk');\n  if (saved) { KEY = saved; api('/v1/passes').then(enter).catch(()=>localStorage.removeItem('psk')); }\n}\n</script>\n</body>\n</html>\n";
